// keykin/vectors/behaviour.json, generated by the TypeScript reference: the Kotlin port must agree.
package keykin

import org.json.JSONObject
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals

class BehaviourTest {
    private val v = JSONObject(File(System.getProperty("keykin.behaviour")).readText())
    private val g = v.getString("g")
    private val rec = JSONObject(Event.of(v.getJSONObject("record")).content)
    private fun code(f: () -> Unit) = try { f(); "ok" } catch (e: KeykinException) { e.code }
    private fun strs(a: org.json.JSONArray) = (0 until a.length()).map { a.getString(it) }

    @Test fun records() { val cs = v.getJSONObject("cases").getJSONArray("records"); for (k in 0 until cs.length()) { val c = cs.getJSONObject(k); assertEquals(c.getString("expect"), code { Record.check(Event.of(c.getJSONObject("event")), g) }, c.getString("name")) } }
    @Test fun locks() { val cs = v.getJSONObject("cases").getJSONArray("locks"); for (k in 0 until cs.length()) { val c = cs.getJSONObject(k); val l = c.getJSONObject("lock")
        assertEquals(if (c.isNull("expect")) null else c.getString("expect"), checkAssertion(g, l.getString("pub"), l.getString("rp"), unhex(c.getString("what")), c.getJSONObject("assertion")), c.getString("name")) } }
    @Test fun membership() {
        val cs = v.getJSONObject("cases").getJSONArray("membership")
        for (k in 0 until cs.length()) {
            val c = cs.getJSONObject(k); val e = c.getJSONObject("expect")
            val m = Membership.compute(rec, (0 until c.getJSONArray("changes").length()).map { Event.of(c.getJSONArray("changes").getJSONObject(it)) })
            val name = c.getString("name")
            assertEquals(strs(e.getJSONArray("devices")), m.devices, "$name: devices")
            assertEquals(strs(e.getJSONArray("removed")), m.removed, "$name: removed")
            assertEquals(strs(e.getJSONArray("refused")), m.refused, "$name: refused")
            assertEquals(e.optString("backup"), m.backup ?: "", "$name: backup")
            assertEquals(e.getBoolean("invariant"), m.invariant, "$name: invariant")
            e.optJSONObject("locks")?.let { el -> for (d in el.keySet()) assertEquals(if (el.isNull(d)) null else el.getString(d), m.locks[d], "$name: lock of ${d.take(8)}") }
            val es = e.getJSONObject("seats"); for (sid in es.keySet()) assertEquals(if (es.isNull(sid)) null else es.getString(sid), m.seats[sid], "$name: $sid")
        }
    }
    @Test fun approvals() {
        val cs = v.getJSONObject("cases").getJSONArray("approvals")
        for (k in 0 until cs.length()) {
            val c = cs.getJSONObject(k)
            val changes = (0 until c.getJSONArray("changes").length()).map { Event.of(c.getJSONArray("changes").getJSONObject(it)) }
            // The authority of the membership the case names (the record plus its changes).
            val devices = (0 until rec.getJSONArray("members").length()).map { member(rec.getJSONArray("members").getJSONObject(it)) }
            val recDev = devices.filter { it.kind == "device" }
            val added = changes.map { JSONObject(it.content).getJSONObject("change").getJSONObject("add").getString("key") }
            val locks = recDev.associate { it.key to listOfNotNull(it.lock) }
            val auth = Authority(g, rec.getJSONObject("epoch").getString("id"), (recDev.map { it.key } + added).toSet(), locks,
                setOf(devices.first { it.kind == "backup" }.key), devices.mapNotNull { it.host }.toSet(), 3 * 86400)
            val expect = if (c.isNull("expect")) null else c.getString("expect")
            assertEquals(expect, Approvals.check(auth, c.getJSONArray("list"), c.getJSONObject("approval")), c.getString("name"))
        }
    }
}
